      <div className="tab-wrap">
      <div className="tab-section tab-section-yellow">Release QE View</div>
      <div style={{ marginTop: 8 }}>
        {release ? `Welcome to the Release QE view for ${release}` : "Welcome to the Release QE view for"}
      </div>
    </div>
  );
}
